const CACHE='nexus-workspace-v4';const ASSETS=["./navigation.js","./navigation.css","./output.js","./jspdf.umd.min.js","./nexus-logo.png","./nexus-logo.svg","./", "./index.html", "./home.css", "./mobile.css", "./register.js", "./evaluation-backup.js", "./manifest.webmanifest", "./tools/bewertung.html", "./tools/exit.html", "./tools/protokoll.html", "./icons/icon-180.png", "./icons/icon-192.png", "./icons/icon-512.png"];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nexus-workspace-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request)));});